                if (!dx && !dy) continue;
                const x = next.x + dx,
                  y = next.y + dy;
                if (!walkable(x, y)) continue;
                const score = ready.filter(
                    (s) => Math.max(Math.abs(s.x - x), Math.abs(s.y - y)) <= 1,
                  ).length,
                  dist = Math.max(Math.abs(p.x - x), Math.abs(p.y - y));
