  let equipmentValueCache = null;
  function equipmentScorePrefix(v) {
    return v.complete ? (v.estimated ? "≈ " : "") : "≥ ";
  }
  function equipmentScoreHint() {
    return (
      t("穿戴装备、工具和坐骑估值 ÷ 1,000,000；不含家园。") +
      " " +
      t(
        "强化装备忽略 +N 挂单与成交价，采用同品质底装价加标准重做期望成本。统一强化100级、无精通和家园；计失败回退、碎片或核心及保护卷轴，比较保护起点后取较低参考。不是原生P50、实际投入或战斗力。缺少保护报价或旧超限装备时仅显示已知下限（≥）。",
      )
    );
  }
  function syncInspectScores() {
    const live = store.state.inspect,
      fmt = globalThis.DVIEquipmentValue.formatScore;
    for (const gear of document.querySelectorAll(".inspect-gear")) {
      const who = gear.closest(".ranks-sheet")?.querySelector("b")?.textContent.trim() || "";
      let note = gear.querySelector("[data-dvi-inspect-score]");
      if (
        gear.closest("[hidden]") ||
        !live?.name ||
        live.hidden ||
        (who !== live.name && !who.startsWith(live.name + " ("))
      ) {
        note?.remove();
        continue;
      }
      if (!note) {
        note = document.createElement("p");
        note.dataset.dviInspectScore = "";
        note.dataset.noI18n = "";
        note.style.cssText = "flex:1 0 100%";
        gear.prepend(note);
      }
      const v = equipmentValuer.value(
        { equipment: live.gear, houseCells: [], house: {} },
        store.state.books,
      );
      const text = t("装备评分") + "\u00a0" + equipmentScorePrefix(v) + fmt(v.score);
      setNativeText(note, text);
      note.title = equipmentScoreHint();
    }
  }
  function syncEquipmentValue() {
    if (typeof insightFeatureEnabled === "function" && !insightFeatureEnabled("equipment")) return;
    syncInspectScores();
    const p = store.state.player;
    if (!p) return;
    // Enhancement slots also have data-worn; only the native equipment grid is a host.
    for (const stray of document.querySelectorAll(".dvi-equipment-value"))
      if (!stray.hasAttribute("data-dvi-score-head")) stray.remove();
    const active = new Set();
    for (const worn of document.querySelectorAll(".worn[data-worn]:not([hidden])")) {
      const mobile = worn.closest("[data-m-worn-home]"),
        head = mobile?.previousElementSibling || worn.closest(".panel")?.querySelector("h2");
      if (!head) continue;
      let box = head.querySelector("[data-dvi-score-head]");
      if (!box) {
        box = document.createElement("details");
        box.className = "dvi-equipment-value";
        box.dataset.dviScoreHead = "";
        box.dataset.noI18n = "";
        box.innerHTML = "<summary></summary><div></div>";
        const meta = head.querySelector("[data-panel-meta]");
        if (meta) meta.before(box);
        else head.append(box);
        for (const event of ["click", "pointerdown", "keydown"])
          box.addEventListener(event, (e) => e.stopPropagation());
      }
      active.add(box);
      if (box.hidden) box.hidden = false;
      const key = JSON.stringify([
        p.id,
        p.equipment,
        p.house,
        p.houseCells,
        store.state.quoteRevision,
        Math.floor(Date.now() / 60000),
      ]);
      if (equipmentValueCache?.key !== key)
        equipmentValueCache = { key, value: equipmentValuer.value(p, store.state.books) };
      const v = equipmentValueCache.value;
      const score = globalThis.DVIEquipmentValue.formatScore;
      setNativeText(
        box.querySelector("summary"),
        t("装备评分") + " " + equipmentScorePrefix(v) + score(v.score),
      );
      box.querySelector("summary").title = equipmentScoreHint();
      const html =
        ["战斗装备", "工具", "坐骑"]
          .map((name, i) => "<span>" + t(name) + "</span><b>" + score(v.parts[i] / 1e6) + "</b>")
          .join("") +
        "<small>" +
        t("强化按统一重做期望成本估值；≈为参考，≥为缺价下限。") +
        "</small>";
      const body = box.querySelector("div");
      if (body.innerHTML !== html) body.innerHTML = html;
      const meta = head.querySelector("[data-panel-meta]");
      if (meta && /^(?:combat|战斗等级)\s+\d+$/i.test(meta.textContent.trim()))
        setNativeText(meta, t("战斗等级 {level}", { level: meta.textContent.match(/\d+/)[0] }));
    }
    for (const box of document.querySelectorAll("[data-dvi-score-head]"))
      if (!active.has(box) && !box.hidden) box.hidden = true;
  }
  const equipmentValueStyle = document.createElement("style");
  equipmentValueStyle.textContent =
    "[data-dvi-score-head]{position:relative;display:inline-block;margin-left:auto;margin-right:8px;vertical-align:middle;font-size:11px;font-weight:400;letter-spacing:0;line-height:1.4}" +
    "[data-dvi-score-head][hidden]{display:none}[data-dvi-score-head]>summary{cursor:pointer;white-space:nowrap;color:var(--brass)}" +
    "[data-dvi-score-head]>div{position:absolute;right:0;top:100%;z-index:5;min-width:148px;padding:9px 12px;display:grid;grid-template-columns:1fr auto;gap:5px 16px;border:1px solid var(--edge);border-radius:4px;background:var(--panel);box-shadow:0 3px 10px #0003;color:var(--ink)}" +
    "[data-dvi-score-head] b{font-weight:400;font-variant-numeric:tabular-nums}[data-dvi-score-head] small{grid-column:1/-1;color:var(--ink-faint)}";
  (document.head || document.documentElement).append(equipmentValueStyle);

  // ---- src/combat-metrics-ui.js ----
  /* Effective damage from received/live client state. No game controls or requests. */
  function createDamageMeter(data) {
    let key = null,
      last = null,
      segments = [],
      raidId = null,
      raidStart = null,
      raidHits = [],
      takenHits = [],
      takenStart = null,
      takenKnown = false;
    const windowTicks = 100;
    return {
      reset() {
        key = null;
        last = null;
        segments = [];
        raidId = null;
        raidStart = null;
        raidHits = [];
        takenHits = [];
        takenStart = null;
        takenKnown = false;
      },
      taken(event) {
        if (
          !key ||
          event.kind !== "hit" ||
          event.by !== "monster" ||
          !Number.isFinite(event.damage) ||
          event.damage < 0
        )
          return;
        takenKnown = true;
        takenHits.push({ tick: event.tick, damage: event.damage });
        takenHits = takenHits.filter((h) => h.tick > event.tick - windowTicks);
      },
      takenReport(tick) {
        const seconds =
            takenStart === null ? 0 : Math.max(0, Math.min(windowTicks, tick - takenStart)) * 0.6,
          damage = takenKnown
            ? takenHits
                .filter((h) => h.tick > tick - windowTicks && h.tick <= tick)
                .reduce((n, h) => n + h.damage, 0)
            : null;
        return { damage, dps: damage !== null && seconds >= 3 ? damage / seconds : null };
      },
      sample(p) {
        const zone = data.world.zones.find((z) => z.id === p?.route?.zoneId),
          monster = data.combat.monsters.find((m) => m.id === zone?.monsterId),
          next = monster ? p.id + ":" + zone.id : null;
        if (next !== key) {
          key = next;
          last = null;
          segments = [];
          takenHits = [];
          takenStart = null;
          takenKnown = false;
        }
        if (!monster) return null;
        if (takenStart === null) takenStart = p.lastTick;
        const progress = Number.isFinite(p.foeHp)
          ? p.foeIndex == null
            ? 0
            : monster.hp - Math.max(0, Math.min(monster.hp, p.foeHp))
          : null;
        const snap = {
          tick: p.lastTick,
          progress,
          kills: p.tally?.monsters?.[monster.id] ?? 0,
          deaths: p.tally?.deaths ?? 0,
          foe: p.foeIndex,
        };
        if (last && snap.tick !== last.tick) {
          const dt = snap.tick - last.tick,
            kills = snap.kills - last.kills,
            damage = kills * monster.hp + (progress ?? 0) - (last.progress ?? 0);
          if (dt <= 0 || dt > 200 || kills < 0 || snap.deaths !== last.deaths) {
            segments = [];
            takenHits = [];
            takenStart = p.lastTick;
            takenKnown = false;
          } else if (
            progress !== null &&
            last.progress !== null &&
            damage >= 0 &&
            !(kills === 0 && last.foe !== snap.foe && last.progress > 0)
          )
            segments.push({ from: last.tick, to: snap.tick, damage });
          else segments = [];
        }
        last = snap;
        segments = segments.filter((s) => s.to > snap.tick - windowTicks);
        let ticks = 0,
          damage = 0;
        for (const s of segments) {
          const kept = s.to - Math.max(s.from, snap.tick - windowTicks);
          ticks += kept;
          damage += (s.damage * kept) / (s.to - s.from);
        }
        return { damage, seconds: ticks * 0.6, dps: ticks >= 5 ? damage / (ticks * 0.6) : null };
      },
      raid(event, id) {
        if (event.kind === "bossGone" || raidId !== id) {
          raidId = id;
          raidStart = null;
          raidHits = [];
        }
        if (event.kind !== "raidHit" || !Number.isFinite(event.damage) || event.damage < 0) return;
        if (raidStart === null || event.tick < raidStart) {
          raidStart = event.tick;
          raidHits = [];
        }
        raidHits.push({ tick: event.tick, damage: event.damage });
        raidHits = raidHits.filter((h) => h.tick > event.tick - windowTicks);
      },
      raidReport(tick) {
        const seconds =
            raidStart === null ? 0 : Math.max(0, Math.min(windowTicks, tick - raidStart)) * 0.6,
          damage = raidHits
            .filter((h) => h.tick > tick - windowTicks && h.tick <= tick)
            .reduce((n, h) => n + h.damage, 0);
        return { damage, seconds, dps: seconds >= 3 ? damage / seconds : null };
      },
    };
  }
  const damageMeter = createDamageMeter(GAME_DATA);
  store.subscribeCombat((event) => {
    if (!insightFeatureEnabled("combatMetrics")) return;
    if (event.kind === "reset") damageMeter.reset();
    else if (event.kind === "hit") damageMeter.taken(event);
    else damageMeter.raid(event, store.state.player?.id);
  });
  let combatMetricsBox = null;
  function syncCombatMetrics() {
    if (typeof insightFeatureEnabled === "function" && !insightFeatureEnabled("combatMetrics"))
      return;
    const p = store.state.player,
      report = damageMeter.sample(p);
    if (document.hidden) return;
    const host = document.querySelector("[data-combat-hud]");
    if (
      !p ||
      !report ||
      document.documentElement.classList.contains("m-on") ||
      !host ||
      host.hidden
    ) {
      combatMetricsBox?.remove();
      combatMetricsBox = null;
      return;
    }
    if (!combatMetricsBox) {
      combatMetricsBox = document.createElement("details");
      combatMetricsBox.className = "dvi-combat-metrics";
      combatMetricsBox.dataset.noI18n = "";
      combatMetricsBox.innerHTML =
        '<summary><span data-dps-value></span><span data-taken-rate></span></summary><div class="dvi-native-breakdown"><span data-damage-label></span><span data-damage-value></span><span data-taken-label></span><span data-taken-value></span><span data-measured-label></span><span data-measured-value></span></div><p class="dvi-note" data-damage-note></p>';
      for (const event of ["click", "pointerdown", "keydown"])
        combatMetricsBox.addEventListener(event, (e) => e.stopPropagation());
    }
    if (combatMetricsBox.parentElement !== host) host.append(combatMetricsBox);
    const box = combatMetricsBox,
      taken = damageMeter.takenReport(p.lastTick);
    setNativeText(
      box.querySelector("[data-dps-value]"),
      "DPS " + (report.dps === null ? t("观测中") : fmt(report.dps, 2)),
    );
    setNativeText(
      box.querySelector("[data-taken-rate]"),
      t("承伤/s") + " " + (taken.dps === null ? "—" : fmt(taken.dps, 2)),
    );
    for (const [key, text] of [
      ["damage-label", "近一分钟伤害"],
      ["taken-label", "近一分钟承伤"],
      ["measured-label", "观测时长"],
    ])
      setNativeText(box.querySelector("[data-" + key + "]"), t(text));
    setNativeText(
      box.querySelector("[data-damage-value]"),
      report.seconds ? fmt(report.damage, 1) : "—",
    );
    setNativeText(
      box.querySelector("[data-taken-value]"),
      taken.damage === null ? "—" : fmt(taken.damage, 1),
    );
    setNativeText(
      box.querySelector("[data-measured-value]"),
      i18n.remainingDuration(report.seconds),
    );
    setNativeText(
      box.querySelector("[data-damage-note]"),
      t(
        "DPS 按有效掉血统计，含走路与补给；承伤按已收到的受击事件统计，缺数据时显示 —。重连后重新观测。",
      ),
    );
  }
  const combatMetricsStyle = document.createElement("style");
  combatMetricsStyle.textContent = `
.combat-hud .dvi-combat-metrics{margin-top:7px;padding-top:6px;border-top:1px solid var(--edge);color:var(--ink);font:400 11px/1.4 var(--sans);font-variant-numeric:tabular-nums}
.dvi-combat-metrics summary{display:flex;align-items:center;justify-content:space-between;gap:8px;cursor:pointer;color:var(--brass)}.dvi-combat-metrics .dvi-note{font-size:10px;color:var(--ink-muted);margin:5px 0 0}.dvi-combat-metrics .dvi-native-breakdown{margin:6px 0}
.dvi-combat-metrics>summary:after{content:'▾';font-size:10px}.dvi-combat-metrics[open]>summary:after{transform:rotate(180deg)}
html.m-on .dvi-combat-metrics{display:none!important}
html.dvi-insights.m-on .m-top .health{position:relative;gap:5px}
html.dvi-insights.m-on .m-top .health .health-bar{width:72px;height:14px;border-radius:4px}
html.dvi-insights.m-on .m-top .health [data-health]{display:block!important;position:absolute;left:auto;right:0;bottom:auto;top:50%;transform:translateY(-50%);width:72px;text-align:center;font:500 11px/1 var(--sans);color:var(--ink);text-shadow:0 1px 1px var(--panel);white-space:nowrap;pointer-events:none;font-variant-numeric:tabular-nums}
`;
  document.documentElement.append(combatMetricsStyle);
  const combatMetricsInterval = setInterval(syncCombatMetrics, 600);
  window.addEventListener("pagehide", (e) => {
    if (!e.persisted) clearInterval(combatMetricsInterval);
  });

  // ---- src/links-ui.js ----
  /* User-requested link to Alice's public simulator. No automatic navigation or data export. */
  const SIMULATOR_URL = "https://dvi-lab.pages.dev/";
  function mountSimulatorLinks() {
    if (typeof insightFeatureEnabled === "function" && !insightFeatureEnabled("simulator")) return;
    for (const nav of document.querySelectorAll(".nav-strip")) {
      let link = nav.querySelector("[data-dvi-simulator]");
      if (!link) {
        link = document.createElement("a");
        link.className = "nav-icon dvi-native-simulator";
        link.dataset.dviSimulator = "";
        link.dataset.noI18n = "";
        link.href = SIMULATOR_URL;
        link.target = "_blank";
        link.rel = "noopener noreferrer";
        link.referrerPolicy = "no-referrer";
        link.innerHTML =
          '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 3l3 1 10 10-3 3L4 7zM3 21l4-4m-2-2 4 4M20 3l-3 1-5 5m3 3 5-5zM17 17l4 4m-6-2 4-4"/></svg>';
        nav.insertBefore(link, nav.querySelector(".nav-more-menu"));
      }
      const label = t("Alice战斗模拟器");
      if (link.title !== label) link.title = label;
      if (link.getAttribute("aria-label") !== label) link.setAttribute("aria-label", label);
    }
  }

  // ---- src/appearance-ui.js ----
  /* Local typography and finish for the existing game UI. No fonts or assets fetched. */
